 public class SafeNumber:NumericUpDown {
  public bool Committing;public Action<int> ScrollRequested;
  public bool TryRead(out decimal number){
   string text=Text.Trim().Replace(',','.');
   return decimal.TryParse(text,NumberStyles.AllowLeadingSign|NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out number)&&number>=Minimum&&number<=Maximum&&decimal.Round(number,DecimalPlaces)==number;
  }
  public void Commit(decimal number){Committing=true;try{UserEdit=false;Value=number;UpdateEditText();}finally{Committing=false;}}
  protected override void ValidateEditText(){decimal number;if(TryRead(out number))Commit(number);}
  protected override void OnMouseWheel(MouseEventArgs e){if(ScrollRequested!=null)ScrollRequested(e.Delta);}
 }
 public class SafeSlider:TrackBar {
  public Action<int> ScrollRequested;protected override void OnMouseWheel(MouseEventArgs e){if(ScrollRequested!=null)ScrollRequested(e.Delta);}
 }
