  bool VisibleField(string key){if(key.StartsWith("Micro"))return p.Kind==0&&p.CycloidLayout==1;if(key=="RingBridge")return p.Kind==0&&p.IntegratedRing;if(key.StartsWith("Model"))return modelSettings!=null&&modelSettings.Checked;return new[]{"Ratio","Overall","Shaft","Thickness","Wall","InputRpm","MotorFrame","MotorMount","MotorPilot","MotorHole","MotorLength"}.Contains(key)||(p.Kind==0&&new[]{"Radius","Roller","Eccentric","Clearance","Bore","OutputPins","OutputPin","OutputRadius","Web","Segments"}.Contains(key))||(p.Kind==0&&p.Discs==2&&key=="DiscGap")||(p.BearingSimulation&&new[]{"Bore","BearingInner","BearingWidth","BallDiameter","BallCount"}.Contains(key))||(p.Kind>0&&(key=="Teeth"||key=="OutputShaft"))||((p.Kind==1||p.Kind==3)&&key=="Module")||(p.Kind==2&&(key=="Pitch"||key=="Center"))||(p.Kind==3&&new[]{"Planets","PlanetPin","RatioTolerance","StageGap","IntermediateShaft"}.Contains(key));}
  void AddNumber(string key,string titleText,decimal min,decimal max,int digits,decimal step,bool slider){
   var panel=new Panel{Width=286,Height=slider?84:61,Margin=new Padding(0,5,0,0)};panel.Controls.Add(new Label{Text=titleText,Width=286,Height=24,Location=new Point(0,0),Font=new Font("Segoe UI",9)});
   var n=new SafeNumber{Minimum=min,Maximum=max,DecimalPlaces=digits,Increment=step,Width=112,Location=new Point(168,25),TextAlign=HorizontalAlignment.Right,AccessibleName=titleText};n.ScrollRequested=ScrollSide;numbers[key]=n;boxes[key]=panel;panel.Controls.Add(n);tips.SetToolTip(n,"От "+min+" до "+max+". Точность: "+digits+" знаков. Точка и запятая допустимы.");
   n.TextChanged+=(s,e)=>{if(!updating&&!n.Committing)MarkDirty();};n.ValueChanged+=(s,e)=>{if(updating||n.Committing)return;updating=true;n.Commit(n.Value);updating=false;CommitAndCalculate();};n.Leave+=(s,e)=>{if(!updating&&dirty)CommitAndCalculate();};
   if(slider){int scale=digits==0?1:100;var t=new SafeSlider{Minimum=(int)(min*scale),Maximum=(int)(max*scale),SmallChange=Math.Max(1,(int)(step*scale)),LargeChange=Math.Max(1,(int)(step*scale*5)),TickStyle=TickStyle.None,TabStop=false,Width=286,Height=27,Location=new Point(0,54)};t.ScrollRequested=ScrollSide;t.ValueChanged+=(s,e)=>{if(updating)return;updating=true;n.Commit((decimal)t.Value/scale);updating=false;CommitAndCalculate();};sliders[key]=t;panel.Controls.Add(t);}
   controls.Controls.Add(panel);
  }
  void MarkDirty(){dirty=true;UpdateCaption();if(canvas!=null){canvas.ShowMotion=false;canvas.Invalidate();}if(banner!=null){banner.BackColor=Color.FromArgb(255,247,221);banner.ForeColor=Color.FromArgb(118,86,12);banner.Text="Ввод ещё не применён. Нажмите «Рассчитать» / Enter или перейдите в другое поле.\nПока показан предыдущий расчёт; экспорт профиля временно выключен.";}if(dxf!=null){dxf.Enabled=false;svgMenu.Enabled=false;dxfMenu.Enabled=false;run.Enabled=false;run.Text="Запустить";if(reset3d!=null)reset3d.Enabled=false;if(step!=null){step.Enabled=false;stepMenu.Enabled=false;print.Enabled=false;}fit.Enabled=false;view.Enabled=false;stageView.Enabled=false;}}
  bool ReadControls(){
   var next=Engine.Clone(p);var values=new Dictionary<string,decimal>();var invalid=new List<string>();
   foreach(var kv in numbers){if(!VisibleField(kv.Key))continue;decimal number;if(!kv.Value.TryRead(out number)){kv.Value.BackColor=Color.MistyRose;invalid.Add(kv.Value.AccessibleName+": число от "+kv.Value.Minimum+" до "+kv.Value.Maximum+", не более "+kv.Value.DecimalPlaces+" знаков после запятой.");}else{values[kv.Key]=number;var prop=typeof(Parameters).GetProperty(kv.Key);prop.SetValue(next,prop.PropertyType==typeof(int)?(object)(int)number:(double)number,null);}}
   if(invalid.Count>0){MarkDirty();banner.BackColor=Color.MistyRose;banner.ForeColor=Color.Maroon;banner.Text="Некорректный ввод\n"+string.Join("\n",invalid.Take(3));notes.Text=string.Join("\r\n\r\n",invalid);return false;}
   updating=true;foreach(var kv in values)numbers[kv.Key].Commit(kv.Value);updating=false;p=next;p.AutoFit=auto.Checked;dirty=false;return true;
  }
  void CommitAndCalculate(){if(updating||canvas==null)return;if(ReadControls())Recalculate();}
  void RefreshFields(){
   bool old=updating;updating=true;int scroll=-controls.AutoScrollPosition.Y;controls.SuspendLayout();kind.SelectedIndex=p.Kind;scheme.SelectedIndex=p.RingOutput?1:0;scheme.Visible=p.Kind==0;schemeLabel.Visible=p.Kind==0;scheme.Enabled=p.CycloidLayout==0;cycleLayout.Visible=cycleLayoutLabel.Visible=p.Kind==0;cycleLayout.SelectedIndex=p.CycloidLayout;dual.Enabled=p.CycloidLayout==0;auto.Visible=true;exportScope.SelectedIndex=p.ExportScope;preset.SelectedIndex=p.MotorPreset;dual.Visible=p.Kind==0;dual.Checked=p.Discs==2;integratedRing.Visible=p.Kind==0;integratedRing.Checked=p.IntegratedRing;bearings.Checked=p.BearingSimulation;bearingPreset.Visible=p.BearingSimulation;bearingPreset.SelectedIndex=p.BearingInner==8&&p.Bore==22&&p.BearingWidth==7?1:p.BearingInner==5&&p.Bore==16&&p.BearingWidth==5?2:0;stageMode.Visible=p.Kind==3;stageLabel.Visible=p.Kind==3;stageMode.SelectedIndex=p.PlanetStages;
   RefreshViews();
   foreach(var kv in numbers){string key=kv.Key;var n=kv.Value;double value=Convert.ToDouble(typeof(Parameters).GetProperty(key).GetValue(p,null));if(value<(double)n.Minimum||value>(double)n.Maximum)throw new InvalidOperationException("Размер "+key+" вне допустимого диапазона.");n.Commit((decimal)value);boxes[key].Visible=VisibleField(key);bool enabled=!(auto.Checked&&((p.Kind==0&&new[]{"Radius","Eccentric","OutputRadius"}.Contains(key))||(p.Overall>0&&((p.Kind==1||p.Kind==3)&&key=="Module"||p.Kind==2&&key=="Center"))));if(p.CycloidLayout==1&&(key=="ModelFlange"||key=="ModelBoltCount"))enabled=false;n.Enabled=enabled;if(sliders.ContainsKey(key)){var t=sliders[key];t.Enabled=enabled;t.Value=(int)((decimal)value*(n.DecimalPlaces==0?1:100));}}
   controls.ResumeLayout();controls.AutoScrollPosition=new Point(0,scroll);updating=old;
  }
  void Apply(Parameters value,bool autoMode){int keepView=canvas.View>=5?canvas.View:0;updating=true;p=Engine.Clone(value);p.AutoFit=autoMode;auto.Checked=autoMode;dirty=false;updating=false;canvas.Phase=0;canvas.StageIndex=0;canvas.View=0;canvas.ShowMotion=false;run.Text="Запустить";RefreshFields();Recalculate();if(keepView>=5)ShowModelView(keepView);}
  void Recalculate(bool fitWorking=true){
   if(updating)return;p.AutoFit=auto.Checked;bool autoFailed=false;string beforeFit=GeometryKey(p);if(auto.Checked&&fitWorking){if(fitKey!=beforeFit){lastFitFailed=!Engine.FitOverall(p);fitKey=GeometryKey(p);}autoFailed=lastFitFailed;}else if(!auto.Checked)fitKey=null;result=Engine.Calculate(p);if(!fitWorking&&auto.Checked&&result.Valid){fitKey=GeometryKey(p);lastFitFailed=false;}string key=GeometryKey(p);if(key!=modelKey||cachedModel==null){cachedModel=CadBuilder.Build(result);modelKey=key;}result.Model=cachedModel;if(autoFailed)result.Error("Автоподбор не нашёл допустимую геометрию. Увеличьте общий габарит или измените отношение, вал, подшипник и размеры деталей.","Overall");
   RefreshFields();dirty=false;canvas.Result=result;if(!result.Valid){canvas.ShowMotion=false;run.Text="Запустить";}canvas.Invalidate();
   title.Text=kinds[p.Kind]+(p.Kind==0&&p.CycloidLayout==1?" Micro":"")+" / "+Engine.F(result.Valid?result.Actual:p.Ratio)+":1"+(p.Kind==3&&result.Stages.Count>1?" / Ступеней: "+result.Stages.Count:"")+(p.Kind==0&&result.Pins>0?(p.IntegratedRing?" / Зацепов: ":" / Роликов: ")+result.Pins:"");
   foreach(var kv in numbers)kv.Value.BackColor=result.BadFields.Contains(kv.Key)?Color.MistyRose:Color.White;
   banner.BackColor=result.Valid?Color.FromArgb(234,244,242):Color.MistyRose;banner.ForeColor=result.Valid?Color.FromArgb(29,89,78):Color.Maroon;
   banner.Text=result.Valid?(p.Kind==0?Engine.Scheme(p)+". ":"Фактическое отношение: "+Engine.F(result.Actual)+":1. ")+"Габарит: "+Engine.F(result.Width)+" × "+Engine.F(result.Height)+" мм; пакет ≈ "+Engine.F(result.Depth)+" мм.\n"+(auto.Checked?"Геометрия подбирается под размер. ":"Ручные размеры. ")+"Проверки пройдены; прочность и ресурс не рассчитаны.":"Ошибки геометрии: "+result.Errors.Count+". Чертёж и экспорт выключены.\n"+string.Join("\n",result.Errors.Take(2));
   if(result.Valid&&result.Model.Valid){var full=result.Model.Bounds();banner.Text+="\nПолная сборка с мотором: "+Engine.F(full[1]-full[0])+" × "+Engine.F(full[3]-full[2])+" × "+Engine.F(full[5]-full[4])+" мм. STEP — все детали в миллиметрах.";}else if(result.Valid){banner.BackColor=Color.FromArgb(255,244,216);banner.ForeColor=Color.FromArgb(115,75,12);banner.Text="Рабочие профили рассчитаны, но 3D-сборка не построена.\n"+string.Join(";",result.Model.Errors.Take(1))+"\nВыберите набор размеров заново или нажмите «Сбросить 3D» для параметров корпуса и опор.";}
   metrics.Rows.Clear();if(result.Model.Valid){var bounds=result.Model.Bounds();result.Metric("Полная 3D-сборка, с мотором",Engine.F(bounds[1]-bounds[0])+" × "+Engine.F(bounds[3]-bounds[2])+" × "+Engine.F(bounds[5]-bounds[4])+" мм");result.Metric("Компонентов 3D",result.Model.Parts.Count.ToString());}foreach(var row in result.Metrics)metrics.Rows.Add(row);bom.Rows.Clear();foreach(var item in result.Items)bom.Rows.Add(item.Name,item.Size,item.Qty,item.Status);metrics.ClearSelection();bom.ClearSelection();
   var text=new StringBuilder();text.AppendLine(result.Valid?"БАЗОВЫЕ ГЕОМЕТРИЧЕСКИЕ ПРОВЕРКИ ПРОЙДЕНЫ":"ОШИБКИ ГЕОМЕТРИИ");foreach(string x in result.Errors)text.AppendLine("\r\n• "+x);text.AppendLine("\r\nСХЕМА И ДОПУЩЕНИЯ");foreach(string x in result.Notes)text.AppendLine("\r\n• "+x);text.AppendLine("\r\nПЕРЕД ИЗГОТОВЛЕНИЕМ\r\nНужны нагрузки, скорости, материал, допуски, КПД, осевая компоновка, маркировки подшипников и точный крепёж по CAD. Геометрия не подтверждает грузоподъёмность. Для двух дисков экспортируются оба профиля с отверстиями; осевые опоры и посадки нужно проверить в CAD.\r\n\r\nФормулы, источники и границы расчёта: Инструкция.md рядом с программой.");text.AppendLine("\r\nПОЛНАЯ 3D-СБОРКА");foreach(var e in result.Model.Errors)text.AppendLine("\r\n• Ошибка 3D: "+e);foreach(var n in result.Model.Notes)text.AppendLine("\r\n• "+n);notes.Text=text.ToString();
   bool profile=result.Valid&&(p.ExportScope==1||result.Model.Valid);step.Enabled=result.Valid&&result.Model.Valid;stepMenu.Enabled=step.Enabled;print.Enabled=step.Enabled;step.Text=p.ExportScope==2?"STEP для печати":"STEP сборка";dxf.Enabled=profile;svgMenu.Enabled=profile;dxfMenu.Enabled=profile;autoButton.Visible=true;reset3d.Enabled=result.Valid;run.Enabled=result.Valid&&(canvas.View<5||result.Model.Valid);fit.Enabled=result.Valid;view.Enabled=result.Valid;stageView.Enabled=result.Valid;UpdateCaption();csv.Text=result.Valid?"CSV деталей":"CSV черновик";
  }
  sealed class ViewOption {public int Id;public string Name;public ViewOption(int id,string name){Id=id;Name=name;}public override string ToString(){return Name;}}
  void RefreshViews(){
   int selected=canvas.View;var items=new List<ViewOption>{new ViewOption(0,"Рабочая передача сверху"),new ViewOption(5,"Полная 3D сборка"),new ViewOption(6,"Разнесённая 3D сборка")};if(p.Kind==0){items.Add(new ViewOption(1,"Только диск A"));if(p.Discs==2)items.Add(new ViewOption(2,"Только диск B"));items.Add(new ViewOption(3,"Осевой вид дисков"));}if(p.Kind==3&&result!=null&&result.Stages.Count>1)items.Add(new ViewOption(3,"Осевая схема ступеней"));if(p.BearingSimulation)items.Add(new ViewOption(4,"Подшипник крупно"));
   view.Items.Clear();foreach(var item in items)view.Items.Add(item);int index=items.FindIndex(x=>x.Id==selected);view.SelectedIndex=index<0?0:index;canvas.View=items[view.SelectedIndex].Id;
   int oldStage=canvas.StageIndex;stageView.Items.Clear();if(p.Kind==3&&result!=null&&result.Stages.Count>1)for(int j=0;j<result.Stages.Count;j++)stageView.Items.Add("Ступень "+(j+1)+" · "+Engine.F(result.Stages[j].Actual)+":1");stageView.Visible=stageView.Items.Count>1;if(stageView.Items.Count>0)stageView.SelectedIndex=Math.Min(oldStage,stageView.Items.Count-1);canvas.StageIndex=Math.Max(0,stageView.SelectedIndex);
  }
  bool HasChanges(){return savedState!=null&&(dirty||ReleaseSupport.Serialize(p)!=savedState);}
  void UpdateCaption(){Text="Gear Lab 1.5.0 · "+(string.IsNullOrEmpty(currentFile)?"Новый проект":Path.GetFileName(currentFile))+(HasChanges()?" *":"");}
  bool ConfirmChanges(){if(!HasChanges())return true;var answer=dialogs.Unsaved(this);return answer==DialogResult.No||answer==DialogResult.Yes&&SaveProject();}
  bool SaveProject(bool saveAs=false){if(!ReadControls())return false;Recalculate();string path=!saveAs&&!string.IsNullOrEmpty(currentFile)?currentFile:dialogs.Save(this,"gear.json",string.IsNullOrEmpty(currentFile)?"Редуктор_"+kinds[p.Kind]+(p.CycloidLayout==1?"_Micro":"")+"_"+Engine.N(p.Ratio)+"к1.gear.json":Path.GetFileName(currentFile));if(path==null)return false;return Attempt(()=>{ReleaseSupport.WriteText(path,ReleaseSupport.Serialize(p),new UTF8Encoding(true));currentFile=path;savedState=ReleaseSupport.Serialize(p);UpdateCaption();footer.Text="Проект сохранён: "+path;});}
  Parameters ParseProject(string text){var value=ReleaseSupport.Parse(text);foreach(var kv in numbers){var prop=typeof(Parameters).GetProperty(kv.Key);double v=Convert.ToDouble(prop.GetValue(value,null));if(double.IsNaN(v)||double.IsInfinity(v)||v<(double)kv.Value.Minimum||v>(double)kv.Value.Maximum||Math.Abs(Math.Round(v,kv.Value.DecimalPlaces)-v)>1e-8)throw new Exception("Параметр "+kv.Key+" вне диапазона/точности поля. Проект не изменён.");}return value;}
  void OpenProject(){string path=dialogs.Open(this);if(path!=null)LoadProjectFile(path);}
  internal void LoadProjectFile(string path){Attempt(()=>{if(new FileInfo(path).Length>131072)throw new Exception("Файл проекта больше 128 КБ.");var next=ParseProject(File.ReadAllText(path,Encoding.UTF8));if(!ConfirmChanges())return;Apply(next,next.AutoFit);currentFile=Path.GetFullPath(path);savedState=ReleaseSupport.Serialize(p);UpdateCaption();footer.Text="Открыт проект: "+currentFile;});}
  void ShowModelView(int id){int index=view.Items.Cast<ViewOption>().ToList().FindIndex(v=>v.Id==id);if(index>=0)view.SelectedIndex=index;}
  internal void ShowFullModel(){ShowModelView(5);}
  bool Attempt(Action action){try{action();return true;}catch(Exception ex){dialogs.Info(this,ex.Message,"Не удалось выполнить действие");return false;}}
  void Export(string type){if(!ReadControls())return;Recalculate();if((type=="step"||p.ExportScope!=1)&&result.Valid&&!result.Model.Valid){dialogs.Info(this,"Полная модель не построена: "+string.Join(";",result.Model.Errors)+"\nУточните параметры 3D или выберите экспорт рабочих профилей.","Экспорт");return;}if(type!="csv"&&!result.Valid){dialogs.Info(this,"Эскиз доступен только после исправления ошибок геометрии.","Экспорт");return;}
   string file=(result.Valid?"Редуктор_":"ЧЕРНОВИК_")+kinds[p.Kind]+(p.CycloidLayout==1?"_Micro":"")+"_"+Engine.N(p.Ratio)+"к1"+(p.Kind==0?(p.RingOutput?"_кольцо":"_центр"):"")+"."+type;string path=dialogs.Save(this,type,file);if(path!=null)Attempt(()=>{Cursor=Cursors.WaitCursor;try{ReleaseSupport.Export(result,type,path);}finally{Cursor=Cursors.Default;}footer.Text="Экспорт сохранён: "+path;});
  }
  internal void Regression(){
   Action<bool,string> assert=(ok,message)=>{if(!ok)throw new Exception("UI: "+message);};
   Apply(new Parameters{Ratio=60,RingOutput=true,Radius=34,Roller=7,Eccentric=1.92},false);assert(!result.Valid&&!dxf.Enabled&&!run.Enabled,"screenshot invalid geometry gate");assert(banner.Text.Contains("Ошибки")&&banner.Text.Contains("Нужно R >"),"visible correction message");
   updating=true;numbers["Radius"].Text="34.5";updating=false;assert(ReadControls()&&Math.Abs(p.Radius-34.5)<1e-9,"decimal point in Russian UI");updating=true;numbers["Radius"].Text="34,75";updating=false;assert(ReadControls()&&Math.Abs(p.Radius-34.75)<1e-9,"decimal comma");
   double old=p.Radius;updating=true;numbers["Radius"].Text="не число";updating=false;assert(!ReadControls()&&p.Radius==old&&!dxf.Enabled,"bad input preserves model");numbers["Radius"].Commit(34);dirty=false;
   Apply(new Parameters{Ratio=60,RingOutput=true,OutputPins=16},true);assert(result.Valid&&p.OutputPins==16&&numbers["Radius"].Value==(decimal)p.Radius,"autosize sync");assert(!numbers["Radius"].Enabled&&numbers["Roller"].Enabled,"auto-derived edit controls");
   double previousRoller=p.Roller;numbers["Roller"].UpButton();assert(Math.Abs(p.Roller-previousRoller-.1)<1e-8,"numeric up arrow commits new value");numbers["Roller"].DownButton();assert(Math.Abs(p.Roller-previousRoller)<1e-8,"numeric down arrow");
   updating=true;numbers["Ratio"].Text="30";updating=false;assert(ReadControls(),"pending ratio commit before export/save");Recalculate();assert(result.Pins==30&&p.Ratio==30,"fresh result");
   assert(sliders["Radius"].Maximum==100000&&sliders["Ratio"].Maximum==20000,"full slider range");
   bool rejected=false;try{ParseProject("{\"Radius\":1001}");}catch{rejected=true;}assert(rejected,"reject out-of-range project instead of clamp");
   var legacy=ParseProject("{\"Ratio\":20}");assert(!legacy.RingOutput,"legacy project retains scheme");
   Apply(new Parameters{Kind=1,Ratio=2,Teeth=20,Module=1},false);assert(result.Valid&&run.Enabled&&dxf.Enabled,"noncycloidal controls");
   for(int k=0;k<4;k++){Apply(Engine.Starter(k),true);assert(result.Valid&&run.Enabled&&dxf.Enabled,"all starters animate/export "+k);assert(VisibleField("Overall")&&VisibleField("MotorMount"),"shared sizing fields "+k);var loaded=ParseProject(new JavaScriptSerializer().Serialize(p));assert(loaded.MotorPreset==2&&loaded.BearingSimulation,"v4 project roundtrip");}
   Apply(Engine.Starter(0),true);dual.Checked=false;assert(p.Discs==1&&result.Valid,"single disc switch");dual.Checked=true;assert(p.Discs==2&&result.Valid,"twin disc switch");
   numbers["Overall"].Commit(100);CommitAndCalculate();assert(result.Valid&&Math.Abs(result.Width-100)<.03,"overall edit changes geometry");
   Apply(Engine.Starter(1),true);numbers["Ratio"].Commit(2.5m);CommitAndCalculate();kind.SelectedIndex=2;assert(p.Kind==2&&result.Valid,"switch type gets independent starter");kind.SelectedIndex=1;assert(p.Kind==1&&p.Ratio==2.5&&result.Valid,"switch type restores parameters");preset.SelectedIndex=1;assert(p.Overall==60&&result.Valid&&p.MotorFrame==42.3,"apply preset through UI");
  }
 }
